// Renders src/tokens.ts as Swift, so the web chrome and the native shell share one palette.
// Run: pnpm tokens   (test/tokens.test.ts fails when the generated file is stale)

import fs from "node:fs";
import { METRICS, TOKENS } from "../src/tokens.ts";

export const OUT = new URL("../apps/macos/DesignSystem/Tokens.generated.swift", import.meta.url);

const hex = (v: string): string | null => {
  const m = /^#([0-9a-f]{6})([0-9a-f]{2})?$/i.exec(v);
  return m ? `0x${m[1].toUpperCase()}${m[2] ? `, ${(parseInt(m[2], 16) / 255).toFixed(2)}` : ""}` : null;
};

export function renderSwift(): string {
  const keys = Object.keys(TOKENS.light).filter((k) => hex(TOKENS.light[k]!) && hex(TOKENS.dark[k]!));
  const colors = keys.map((k) => `    static let ${k} = Color(light: ${hex(TOKENS.light[k]!)}, dark: ${hex(TOKENS.dark[k]!)})`);
  const metrics = Object.entries(METRICS).map(([k, v]) => `    static let ${k}: CGFloat = ${v}`);
  return [
    "// GENERATED by scripts/gen-swift-tokens.ts from src/tokens.ts. Do not edit; run `pnpm tokens`.",
    "",
    "import SwiftUI",
    "",
    "enum Palette {",
    ...colors,
    "}",
    "",
    "enum Metric {",
    ...metrics,
    "}",
    "",
  ].join("\n");
}

if (import.meta.url === `file://${process.argv[1]}`) fs.writeFileSync(OUT, renderSwift());
